-- Table: masterdata_payroll_component
-- Source: accounting_admin_db.sql (1. Master data)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS masterdata_payroll_component (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code           VARCHAR(30)  NOT NULL UNIQUE,
    name           VARCHAR(100) NOT NULL,
    component_type VARCHAR(30)  NOT NULL
                   CHECK (component_type IN ('earning', 'deduction', 'employer_contribution')),
    taxable        BOOLEAN      NOT NULL DEFAULT TRUE,
    coa_id         BIGINT       NOT NULL REFERENCES masterdata_coa(id),
    is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now()
);
